#pragma once

#include <stdint.h>

#include "lvgl.h"

#define NOTIFICATION_EMOJI_SIZES 4

typedef struct {
    uint32_t codepoint;
    lv_image_dsc_t image[NOTIFICATION_EMOJI_SIZES]; /* 20, 24, 28 and 32 px */
} notification_emoji_entry_t;

extern const notification_emoji_entry_t k_notification_emoji[]; /* sorted by codepoint */
extern const unsigned k_notification_emoji_count;
